-- Changelog-item: bloktitels in zinsvorm met groene tint i.p.v. grijze kapitalen.
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-03','verbeterd','Platform','Titels van blokken zijn beter leesbaar',
   'De titel boven een blok stond in kleine grijze hoofdletters en viel daardoor nauwelijks op, zeker op tabbladen met veel blokken onder elkaar. Titels staan nu groter, in gewone schrijfwijze en op een zachtgroene balk, zodat je in één oogopslag ziet waar een blok begint en eindigt. Dit geldt overal in EVA en werkt ook in de donkere modus en bij afdrukken.');
